def span_delete(A,M):
    """yield dropped spans (start,end) such that M[:s]+M[e:]==A"""
    out=[]
    la,lm=len(A),len(M)
    if lm<=la: return out
    for s in range(lm):
        for e in range(s+1,lm+1):
            if M[:s]+M[e:]==A: out.append((s,e))
    return out

def rule_v2(A,items,itemset,alpha):
    if A in itemset or not A: return A
    hits=[]
    for M in items:
        for s,e in span_delete(A,M):
            if any(ch in alpha for ch in M[s:e]):
                hits.append(M); break
    hits=sorted(set(hits))
    return hits[0] if len(hits)==1 else A

def rule_v1(A,items,itemset):
    if A in itemset or not A: return A
    def sub(a,b):
        it=iter(b); return all(c in it for c in a)
    cands=sorted([M for M in items if len(M)>len(A) and sub(A,M)],key=len)
    if not cands: return A
    if len(cands)>1 and len(cands[0])==len(cands[1]): return A
    return cands[0]

def apply(rule,pred,sep):
    lead,b,tail=split_wrapper(pred); A=b.strip()
    if not A: return pred
    parts=A.split(sep) if sep and sep in A else [A]
    return f"{lead}{sep.join(rule(p) for p in parts)}{tail}"

